fetch("/assets/content/gallery/gallery.json").then(e=>e.json()).then(e=>{const t=document.getElementById("gallery");e.forEach(e=>{const l=document.createElement("img");l.src=e.startsWith("/")?e:`/assets/content/gallery/${e}`,l.alt=e,t.appendChild(l)})}).catch(e=>{console.error("Failed to load gallery images:",e);document.getElementById("gallery").innerHTML='<p style="color: red;">Failed to load gallery images.</p>'});